#[path = "solution.rs"]
mod solution;

use solution::{dispatch, Command, Reply, Workshop};

#[test]
fn health_and_empty_summary_are_read_only() {
    let mut workshop = Workshop { name: "Forge".to_string(), ..Workshop::default() };
    let before = workshop.clone();
    assert_eq!(dispatch(&mut workshop, Command::Health), Reply::Text("ready".to_string()));
    assert_eq!(dispatch(&mut workshop, Command::Summary), Reply::Text("Forge|".to_string()));
    assert_eq!(workshop, before);
}

#[test]
fn zones_are_trimmed_stored_and_summarized_in_sorted_order() {
    let mut workshop = Workshop { name: "Shop".to_string(), ..Workshop::default() };
    assert_eq!(dispatch(&mut workshop, Command::AddZone(" beta ".to_string())), Reply::Changed);
    assert_eq!(dispatch(&mut workshop, Command::AddZone("alpha".to_string())), Reply::Changed);
    assert_eq!(dispatch(&mut workshop, Command::Summary), Reply::Text("Shop|alpha,beta".to_string()));
    assert_eq!(dispatch(&mut workshop, Command::AddZone(" beta".to_string())), Reply::Conflict);

    let before = workshop.clone();
    assert_eq!(dispatch(&mut workshop, Command::AddZone(" \t ".to_string())), Reply::Invalid);
    assert_eq!(workshop, before);
}

#[test]
fn tools_require_existing_zones_and_preserve_zone_insertion_order() {
    let mut workshop = Workshop::default();
    assert_eq!(dispatch(&mut workshop, Command::AddZone(" work ".to_string())), Reply::Changed);
    assert_eq!(dispatch(&mut workshop, Command::AddTool { id: 8, name: " Hammer ".to_string(), zone: " work ".to_string() }), Reply::Changed);
    assert_eq!(dispatch(&mut workshop, Command::AddTool { id: 3, name: "Saw".to_string(), zone: "work".to_string() }), Reply::Changed);

    assert_eq!(dispatch(&mut workshop, Command::Zone(" work ".to_string())), Reply::Text("8,3".to_string()));
    assert_eq!(dispatch(&mut workshop, Command::Tool(8)), Reply::Text("8|Hammer|work".to_string()));
    assert_eq!(workshop.tools.get(&8).unwrap().name, "Hammer");
    assert_eq!(workshop.tools.get(&8).unwrap().zone, "work");
}

#[test]
fn failed_tool_additions_are_non_mutating() {
    let mut workshop = Workshop::default();
    dispatch(&mut workshop, Command::AddZone("zone".to_string()));
    dispatch(&mut workshop, Command::AddTool { id: 1, name: "tool".to_string(), zone: "zone".to_string() });

    let cases = [
        (Command::AddTool { id: 1, name: "other".to_string(), zone: "zone".to_string() }, Reply::Conflict),
        (Command::AddTool { id: 2, name: " ".to_string(), zone: "zone".to_string() }, Reply::Invalid),
        (Command::AddTool { id: 2, name: "tool".to_string(), zone: " ".to_string() }, Reply::Invalid),
        (Command::AddTool { id: 2, name: "tool".to_string(), zone: "missing".to_string() }, Reply::NotFound),
    ];
    for (command, expected) in cases {
        let before = workshop.clone();
        assert_eq!(dispatch(&mut workshop, command), expected);
        assert_eq!(workshop, before);
    }
}

#[test]
fn removing_a_tool_updates_its_zone_and_missing_removal_is_stable() {
    let mut workshop = Workshop::default();
    dispatch(&mut workshop, Command::AddZone("z".to_string()));
    dispatch(&mut workshop, Command::AddTool { id: 1, name: "one".to_string(), zone: "z".to_string() });
    dispatch(&mut workshop, Command::AddTool { id: 2, name: "two".to_string(), zone: "z".to_string() });

    assert_eq!(dispatch(&mut workshop, Command::RemoveTool(1)), Reply::Changed);
    assert_eq!(dispatch(&mut workshop, Command::Zone("z".to_string())), Reply::Text("2".to_string()));
    assert_eq!(dispatch(&mut workshop, Command::Tool(1)), Reply::NotFound);

    let before = workshop.clone();
    assert_eq!(dispatch(&mut workshop, Command::RemoveTool(99)), Reply::NotFound);
    assert_eq!(workshop, before);
}

#[test]
fn removing_a_zone_cascades_to_all_assigned_tools() {
    let mut workshop = Workshop::default();
    dispatch(&mut workshop, Command::AddZone("a".to_string()));
    dispatch(&mut workshop, Command::AddZone("b".to_string()));
    dispatch(&mut workshop, Command::AddTool { id: 1, name: "one".to_string(), zone: "a".to_string() });
    dispatch(&mut workshop, Command::AddTool { id: 2, name: "two".to_string(), zone: "a".to_string() });
    dispatch(&mut workshop, Command::AddTool { id: 3, name: "three".to_string(), zone: "b".to_string() });

    assert_eq!(dispatch(&mut workshop, Command::RemoveZone(" a ".to_string())), Reply::Changed);
    assert_eq!(dispatch(&mut workshop, Command::Zone("a".to_string())), Reply::NotFound);
    assert_eq!(dispatch(&mut workshop, Command::Tool(1)), Reply::NotFound);
    assert_eq!(dispatch(&mut workshop, Command::Tool(2)), Reply::NotFound);
    assert_eq!(dispatch(&mut workshop, Command::Tool(3)), Reply::Text("3|three|b".to_string()));

    let before = workshop.clone();
    assert_eq!(dispatch(&mut workshop, Command::RemoveZone("missing".to_string())), Reply::NotFound);
    assert_eq!(dispatch(&mut workshop, Command::RemoveZone(" ".to_string())), Reply::Invalid);
    assert_eq!(workshop, before);
}

